//! The desktop crate's build script: tauri-build reads `tauri.conf.json`, embeds the
//! Windows icon and resolves the capabilities and the app's command manifest at build time.

use std::error::Error;

use tauri_build::{AppManifest, Attributes};

/// The app's own commands. tauri-build generates an `allow-<command>` and a
/// `deny-<command>` permission for each, in `permissions/autogenerated/` (committed and
/// pinned by `scripts/tauri-hardening.mjs`), and the UI can call one only when a
/// capability grants its `allow-<command>`. `permissions/default.toml` keeps the ACL on
/// for app commands even if this list were empty (ADR-0017).
const COMMANDS: &[&str] = &[
    "server_profile",
    "set_server_profile",
    "check_server",
    "login",
    "login_mfa",
    "logout",
    "register",
    "step_up",
    "mfa_enroll",
    "mfa_confirm",
    "mfa_reset",
    "me",
    "change_password",
    "sessions",
    "revoke_session",
    "users",
    "patch_user",
    "invites",
    "create_invite",
    "revoke_invite",
];

fn main() -> Result<(), Box<dyn Error>> {
    tauri_build::try_build(Attributes::new().app_manifest(AppManifest::new().commands(COMMANDS)))?;
    Ok(())
}
